export type LanguageCode = "en" | "es" | "de" | "fr" | "ar" | "pt";

export const SUPPORTED_LANGUAGES: ReadonlyArray<{
  code: LanguageCode;
  pickerLabel: string;
  englishName: string;
  nativeName: string;
}> = [
  { code: "en", pickerLabel: "🇬🇧 English", englishName: "English", nativeName: "English" },
  { code: "es", pickerLabel: "🇪🇸 Spanish (Español)", englishName: "Spanish", nativeName: "Español" },
  { code: "de", pickerLabel: "🇩🇪 German (Deutsch)", englishName: "German", nativeName: "Deutsch" },
  { code: "fr", pickerLabel: "🇫🇷 French (Français)", englishName: "French", nativeName: "Français" },
  { code: "ar", pickerLabel: "🇸🇦 Arabic (العربية)", englishName: "Arabic", nativeName: "العربية" },
  { code: "pt", pickerLabel: "🇵🇹 Portuguese (Português)", englishName: "Portuguese", nativeName: "Português" }
] as const;

export const LANGUAGE_CODES: readonly LanguageCode[] = SUPPORTED_LANGUAGES.map(language => language.code);
export const LANGUAGE_PICKER_TITLE = "🌐 <b>Choose your language</b>\nElige tu idioma · Wähle deine Sprache · Choisis ta langue · اختر لغتك · Escolhe o teu idioma";

export function isLanguageCode(value: unknown): value is LanguageCode {
  return typeof value === "string" && (LANGUAGE_CODES as readonly string[]).includes(value);
}

export function normalizeLanguage(value: unknown): LanguageCode {
  return isLanguageCode(value) ? value : "en";
}

export function languageDisplayName(language: LanguageCode): string {
  return SUPPORTED_LANGUAGES.find(item => item.code === language)?.pickerLabel || "🇬🇧 English";
}

