const dictionaries: Record<LanguageCode, Partial<Dictionary>> = {
  en,
  es,
  de,
  fr,
  ar,
  pt
};

export const TRANSLATION_KEYS = Object.keys(en) as TranslationKey[];

export function translate(
  language: LanguageCode,
  key: TranslationKey,
  params: Record<string, string | number> = {}
): string {
  const template = dictionaries[normalizeLanguage(language)][key] || en[key] || key;
  return template.replace(/\{([A-Za-z][A-Za-z0-9_]*)\}/g, (_match, name: string) => String(params[name] ?? ""));
}

export function translationOrEnglish(language: LanguageCode, key: TranslationKey): string {
  return dictionaries[normalizeLanguage(language)][key] || en[key] || key;
}

