export function orderStatusLabel(language: LanguageCode, status: string): string {
  if (normalizeLanguage(language) === "en") return status;
  return statusLabels[normalizeLanguage(language)][status] || status;
}

export function aiLanguageInstruction(language: LanguageCode): string {
  const item = SUPPORTED_LANGUAGES.find(languageItem => languageItem.code === normalizeLanguage(language));
  return `Reply in ${item?.englishName || "English"}${item && item.nativeName !== item.englishName ? ` (${item.nativeName})` : ""}. Keep FL order codes, URLs, usernames, product IDs, and other technical values exactly unchanged.`;
}

export function ttsLanguage(language: LanguageCode): string | null {
  switch (normalizeLanguage(language)) {
    case "en": return "en";
    case "es": return "es";
    case "fr": return "fr";
    default: return null;
  }
}

export const CUSTOMER_START_BUTTON_TEXTS: readonly string[] = LANGUAGE_CODES.map(code => translate(code, "startButton"));
export const CUSTOMER_LANGUAGE_BUTTON_TEXTS: readonly string[] = LANGUAGE_CODES.map(code => translate(code, "languageButton"));
